package com.creativeblisslabs.peqlearn.app.audio

import android.content.Context
import android.media.SoundPool
import android.util.Log
import java.io.IOException
import java.util.concurrent.ConcurrentHashMap

class DrumKitLoader(private val context: Context, private val soundPool: SoundPool) {

    // Maps "KIT_NAME_PAD_INDEX" -> SoundPool ID (e.g., "ELECTRONIC_808_0" -> 1)
    val kitSampleMap = ConcurrentHashMap<String, Int>()
    val loadedAssetsStatus = ConcurrentHashMap<Int, Boolean>()

    // The exact 5 professional kit folder names generated by your Python script
    val availableKits = listOf(
        "ACOUSTIC_STUDIO",
        "METAL_CORE",
        "ELECTRONIC_808",
        "HIPHOP_TRAP",
        "LOFI_CHILL"
    )

    // The rigid 16-pad hardware blueprint layout used during sorting
    val padLabels = listOf(
        "KICK", "SNARE", "HIHAT_CLOSED", "CLAP",
        "KICK_ALT", "SNARE_ALT", "HIHAT_OPEN", "CRASH",
        "TOM_HI", "TOM_MID", "TOM_LO", "RIDE",
        "BASS_SUB", "RIM_CLICK", "PERC", "FX"
    )

    init {
        // Set up the listener to flag when samples are fully loaded into memory
        soundPool.setOnLoadCompleteListener { _, sampleId, status ->
            if (status == 0) {
                loadedAssetsStatus[sampleId] = true
            } else {
                Log.e("DrumKitLoader", "Failed to load sample ID: $sampleId")
            }
        }
    }

    /**
     * Loops through all kits and loads all 16 pads sequentially into memory.
     */
    fun preloadAllKits() {
        availableKits.forEach { kitName ->
            for (padIndex in 0..15) {
                val label = padLabels[padIndex]
                // Match the exact filename structure in assets: drums/fingerdrumming/$kitName/$padIndex-$label.wav
                val assetPath = "drums/fingerdrumming/$kitName/$padIndex-$label.wav"

                try {
                    context.assets.openFd(assetPath).use { assetDescriptor ->
                        val soundId = soundPool.load(assetDescriptor, 1)
                        
                        // Create a predictable O(1) lookup key
                        val mapKey = "${kitName}_$padIndex"
                        kitSampleMap[mapKey] = soundId
                    }
                } catch (e: IOException) {
                    Log.e("DrumKitLoader", "Missing expected file path target: $assetPath", e)
                }
            }
        }
        Log.i("DrumKitLoader", "Preloading complete. Total mapped pads: ${kitSampleMap.size}")
    }
}